package com.mannschaft.spike.pattern.jobmatching; import com.mannschaft.spike.pattern.chat.api.ChatApi; import com.mannschaft.spike.ModuleEventListener; /** 自モジュールで保険購読しchat.apiだけを呼ぶ検体。 */ public class JobListener { private final ChatApi api; public JobListener(ChatApi api) { this.api=api; } @ModuleEventListener(id="job-confirm") public void confirm(JobEvent event) { api.confirm(event.roomId()); } }